static const int MOD = 1000000007;

/*
Interpretation:

Level (1, L): the sequence [1].
For k > 1, a sequence is in level (k, L) iff it is a concatenation of at least L
sequences from level (k-1, L).

Therefore, every level-k sequence consists only of 1's, and its length belongs to:
S1 = {1}
Sk = { m1 + ... + mt | t >= L, each mi in S(k-1) }

If A_k is the set of possible lengths at level k, then:
A_1 = {1}
A_k = all integers >= L^(k-1)

Reason:
By induction, if A_(k-1) = {n >= L^(k-2)}, then any sum of t>=L such numbers is
at least L * L^(k-2) = L^(k-1), and every integer >= L^(k-1) is achievable
(using enough parts, adjusting by 1's from the previous level interval).
So a subsequence belongs to some level iff it consists entirely of 1's and its
length is either:
- exactly 1, or
- at least L   (for k=2),
which already covers all higher levels too.

Thus:
- If L = 1, any positive number of 1's forms some level.
- If L > 1, valid lengths are 1 or any length >= L.
So invalid lengths are exactly 2..L-1.

We need the number of subsequences of the given sequence that are all 1's and
whose chosen count is valid.

If cnt = number of ones in the array, then the number of subsequences with
exactly t chosen ones is C(cnt, t). Answer is:
sum over valid t of C(cnt, t).

For L = 1: answer = 2^cnt - 1.
For L > 1: answer = 2^cnt - 1 - sum_{t=2}^{L-1} C(cnt, t).

We compute combinations iteratively:
C(cnt, t) from C(cnt, t-1):
C(cnt, t) = C(cnt, t-1) * (cnt - t + 1) / t mod MOD
using modular inverse.
*/

long long modpow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long L;
    cin >> n >> L;

    long long cnt1 = 0;
    for (int i = 0; i < n; ++i) {
        long long x;
        cin >> x;
        if (x == 1) cnt1++;
    }

    long long ans = (modpow(2, cnt1) - 1 + MOD) % MOD;

    if (L > 1) {
        long long upper = min<long long>(cnt1, L - 1);
        if (upper >= 2) {
            vector<long long> inv(upper + 1);
            for (long long i = 1; i <= upper; ++i) inv[i] = modpow(i, MOD - 2);

            long long comb = 1; // C(cnt1, 0)
            for (long long t = 1; t <= upper; ++t) {
                comb = comb * ((cnt1 - t + 1) % MOD) % MOD;
                comb = comb * inv[t] % MOD;
                if (t >= 2) {
                    ans -= comb;
                    if (ans < 0) ans += MOD;
                }
            }
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}

