#define BASE 1000000000

typedef struct {
    int *d;
    int len;
    int cap;
} BigInt;

void bi_init(BigInt *a, long long v) {
    a->cap = 8;
    a->d = (int*)calloc(a->cap, sizeof(int));
    a->len = 0;
    while (v > 0) {
        a->d[a->len++] = (int)(v % BASE);
        v /= BASE;
    }
    if (a->len == 0) a->len = 1;
}

void bi_reserve(BigInt *a, int nc) {
    if (nc <= a->cap) return;
    while (a->cap < nc) a->cap <<= 1;
    a->d = (int*)realloc(a->d, a->cap * sizeof(int));
}

void bi_trim(BigInt *a) {
    while (a->len > 1 && a->d[a->len - 1] == 0) a->len--;
}

void bi_copy(BigInt *dst, const BigInt *src) {
    bi_reserve(dst, src->len);
    memcpy(dst->d, src->d, src->len * sizeof(int));
    dst->len = src->len;
}

void bi_add(BigInt *a, const BigInt *b) {
    int n = (a->len > b->len ? a->len : b->len);
    bi_reserve(a, n + 1);
    long long carry = 0;
    for (int i = 0; i < n || carry; i++) {
        if (i == a->len) a->d[a->len++] = 0;
        long long cur = carry + a->d[i] + (i < b->len ? b->d[i] : 0);
        a->d[i] = (int)(cur % BASE);
        carry = cur / BASE;
    }
}

void bi_sub(BigInt *a, const BigInt *b) { // assume a >= b
    long long carry = 0;
    for (int i = 0; i < a->len; i++) {
        long long cur = (long long)a->d[i] - (i < b->len ? b->d[i] : 0) - carry;
        if (cur < 0) cur += BASE, carry = 1;
        else carry = 0;
        a->d[i] = (int)cur;
    }
    bi_trim(a);
}

void bi_mul_small(BigInt *a, long long m) {
    if (m == 0) {
        a->len = 1;
        a->d[0] = 0;
        return;
    }
    bi_reserve(a, a->len + 8);
    long long carry = 0;
    for (int i = 0; i < a->len; i++) {
        long long cur = carry + 1LL * a->d[i] * m;
        a->d[i] = (int)(cur % BASE);
        carry = cur / BASE;
    }
    while (carry) {
        a->d[a->len++] = (int)(carry % BASE);
        carry /= BASE;
    }
}

void bi_div_small(BigInt *a, long long v) { // exact division assumed
    long long rem = 0;
    for (int i = a->len - 1; i >= 0; i--) {
        long long cur = a->d[i] + rem * BASE;
        a->d[i] = (int)(cur / v);
        rem = cur % v;
    }
    bi_trim(a);
}

void bi_print(const BigInt *a) {
    printf("%d", a->d[a->len - 1]);
    for (int i = a->len - 2; i >= 0; i--) {
        printf("%09d", a->d[i]);
    }
    putchar('\n');
}

